DEFINE FUNCTION fn::get_continent_hierarchy($includeInactive: bool) {
    LET $continents = SELECT * FROM continent WHERE ($includeInactive = true OR isActive = true) ORDER BY code;
    IF array::len($continents) = 0 {
        RETURN [];
    };
    LET $continent_ids = array::map($continents, |$c| $c.id);
    LET $all_regions = SELECT * FROM region WHERE continentId IN $continent_ids AND ($includeInactive = true OR isActive = true) ORDER BY name;
    LET $region_ids = array::map($all_regions, |$r| $r.id);
    LET $all_subregions = SELECT * FROM subRegion WHERE regionId IN $region_ids AND ($includeInactive = true OR isActive = true) ORDER BY name;

    RETURN array::map($continents, |$continent| {
        LET $continent_regions = array::filter($all_regions, |$r| $r.continentId = $continent.id);
        LET $enriched_regions = array::map($continent_regions, |$region| {
            LET $region_subs = array::filter($all_subregions, |$s| $s.regionId = $region.id);
            RETURN $region + { subRegions: $region_subs };
        });
        RETURN $continent + { regions: $enriched_regions };
    });
};
